using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
public void Execute(ExecutionResult result){for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene");string path=File.ReadAllText("Validation/VisualRefinement/next.txt").Trim();var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var terrain=ts.Select(t=>t.GetComponent<Terrain>()).First(t=>t);var trees=ts.Where(t=>t.parent&&(t.parent.name.StartsWith("Vegetation - Source Anchored")||t.parent.name=="Trees"||t.parent.name=="Realistic Ecosystem Supplementary"||t.parent.name.StartsWith("Forest -"))).Where(t=>t.GetComponentsInChildren<Renderer>().Any(r=>r.enabled)).ToArray();var log=new List<string>();int n=0;foreach(var q in new[]{new Vector3(-100,0,0),new Vector3(40,0,30),new Vector3(100,0,-100)}){var t=trees.OrderBy(t=>Vector2.Distance(new Vector2(t.position.x,t.position.z),new Vector2(q.x,q.z))).FirstOrDefault();var target=t?t.position:q;target.y=terrain.SampleHeight(target)+terrain.transform.position.y+2;var pos=target+new Vector3(10,0,-12);if(terrain.SampleHeight(pos)+terrain.transform.position.y<.2f){for(int angle=0;angle<360;angle+=45){var candidate=target+Quaternion.Euler(0,angle,0)*new Vector3(10,0,-12);if(terrain.SampleHeight(candidate)+terrain.transform.position.y>.2f){pos=candidate;break;}}}pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y+1.8f;var go=new GameObject("__VisualQA");var c=go.AddComponent<Camera>();c.farClipPlane=1500;c.fieldOfView=65;c.transform.position=pos;c.transform.LookAt(target);MMSequentialEvidence.Render(c,"Validation/VisualRefinement/"+s.name+"_"+File.ReadAllText("Validation/VisualRefinement/stage.txt").Trim()+"_"+n+".png",1100,750);UnityEngine.Object.DestroyImmediate(go);log.Add(n+"|"+(t?P(t):"none")+"|pos="+pos+"|target="+target);n++;}File.WriteAllLines("Validation/VisualRefinement/"+s.name+"_views.txt",log);File.WriteAllLines("Validation/VisualRefinement/"+s.name+"_trees.txt",trees.Select(t=>P(t)+"|"+string.Join(";",t.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).Select(r=>r.name+":"+string.Join(",",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)))))));result.Log(s.name+" ground views ready");}}
